from __future__ import annotations

import ast
import copy
import json
import pathlib
import shutil
import tempfile
from dataclasses import dataclass

_FLIP_CMP = {ast.Eq: ast.NotEq, ast.NotEq: ast.Eq, ast.Lt: ast.GtE, ast.GtE: ast.Lt,
             ast.Gt: ast.LtE, ast.LtE: ast.Gt, ast.In: ast.NotIn, ast.NotIn: ast.In,
             ast.Is: ast.IsNot, ast.IsNot: ast.Is}
_FLIP_BOOL = {ast.And: ast.Or, ast.Or: ast.And}

LOCK = ".athena/mutation_lock.json"
#: never copied into the mirror: history, databases, caches, other people's artifacts
_SKIP_DIRS = {".git", ".beads", ".athena", "node_modules", "__pycache__", ".pytest_cache",
              ".venv", "venv", ".deepeval", "console", "vendor", "evals", "obsidian-ai-pack"}


@dataclass(frozen=True)
class Mutant:
    """One broken version of the source, and where the break is."""
    path: str
    line: int
    kind: str
    source: str


def _sites(tree: ast.AST, lines: frozenset[int]) -> list[tuple[ast.AST, str]]:
    """Nodes ON the owned lines that carry decidable behaviour. Docstrings and bare string
    constants are skipped: mutating prose yields an equivalent mutant, which is noise."""
    out: list[tuple[ast.AST, str]] = []
    docstrings = set()
    for node in ast.walk(tree):
        if isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            body = getattr(node, "body", [])
            if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant):
                docstrings.add(id(body[0].value))
    for node in ast.walk(tree):
        if getattr(node, "lineno", None) not in lines:
            continue
        if isinstance(node, ast.Compare) and type(node.ops[0]) in _FLIP_CMP:
            out.append((node, f"flip {type(node.ops[0]).__name__}"))
        elif isinstance(node, ast.BoolOp) and type(node.op) in _FLIP_BOOL:
            out.append((node, f"flip {type(node.op).__name__}"))
        elif isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            out.append((node, "drop not"))
        elif isinstance(node, ast.Constant) and id(node) not in docstrings \
                and isinstance(node.value, bool):
            out.append((node, f"{node.value} -> {not node.value}"))
    return out


def mutants(source: str, lines, path: str = "") -> tuple[Mutant, ...]:
    """PURE: every single-point AST mutation on the given lines, in document order.

    One mutation per mutant: a mutant that changes two things cannot tell you which one the
    specs failed to notice.
    """
    owned = frozenset(int(x) for x in lines)
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return ()
    out: list[Mutant] = []
    for index, (_, kind) in enumerate(_sites(tree, owned)):
        clone = ast.parse(source)
        target, _ = _sites(clone, owned)[index]
        line = getattr(target, "lineno", 0)
        if isinstance(target, ast.Compare):
            target.ops = [_FLIP_CMP[type(target.ops[0])]()] + list(target.ops[1:])
        elif isinstance(target, ast.BoolOp):
            target.op = _FLIP_BOOL[type(target.op)]()
        elif isinstance(target, ast.UnaryOp):
            _replace(clone, target, copy.deepcopy(target.operand))
        elif isinstance(target, ast.Constant):
            target.value = not target.value
        out.append(Mutant(path=path, line=line, kind=kind,
                          source=ast.unparse(ast.fix_missing_locations(clone))))
    return tuple(out)


def _replace(tree: ast.AST, old: ast.AST, new: ast.AST) -> None:
    """Swap a node for another in place (used to drop a `not`)."""
    for parent in ast.walk(tree):
        for field, value in ast.iter_fields(parent):
            if value is old:
                setattr(parent, field, new)
                return
            if isinstance(value, list):
                for i, item in enumerate(value):
                    if item is old:
                        value[i] = new
                        return


def scoped_specs(clause_map: dict, spec_cmds: dict, path: str, line: int) -> tuple[str, ...]:
    """PURE: the run_cmds that must notice a break at this line — every OWNER's specs.

    Scoping to a single clause is the error that produced false vacuity in the first probe:
    a line owned by 93 clauses is proved by whichever of them asserts it.
    """
    from lib.clause_map import owners
    ids = set(owners(clause_map, path, line))
    return tuple(cmd for sid, (cid, cmd) in sorted(spec_cmds.items()) if cid in ids)


def summarize(results: tuple[dict, ...]) -> dict:
    """PURE: the report. `survivors` is the answer to "which specs prove nothing".

    A mutant whose spec budget ran out is NOT a survivor: it is undetermined, counted apart,
    and it never claims that anything failed to prove anything.
    """
    def status_of(r):
        return r.get("status", "killed" if r["killed"] else "survived")

    survivors = [r for r in results if status_of(r) == "survived"]
    undetermined = [r for r in results if status_of(r) == "undetermined"]
    unowned = [r for r in results if status_of(r) == "unowned"]
    errors = [r for r in results if status_of(r) not in ("killed", "survived", "undetermined", "unowned")]
    killed = sum(1 for r in results if status_of(r) == "killed")
    decided = killed + len(survivors)
    truncated = any(r.get("budget_exhausted") for r in results)
    state = "FAIL" if survivors else ("INCOMPLETE" if not decided or undetermined or unowned or errors or truncated else "PASS")
    return {
        "mutants": len(results),
        "killed": killed,
        "survived": len(survivors),
        "undetermined": len(undetermined),
        "unowned": len(unowned),
        "tool_errors": len(errors),
        "evaluated": decided,
        "state": state,
        "budget_exhausted": truncated,
        "score": round(killed / decided, 4) if decided else None,
        "survivors": survivors,
    }


MIRROR_MARKER = ".athena-mirror"


class UnsafeMirror(RuntimeError):
    """The mirror path is not something this harness is allowed to delete."""


def default_mirror(repo: str) -> str:
    """PURE-ish (reads the platform temp dir): where a sweep runs when nobody says where.

    The documented default was `.athena/mutation_mirror`, which is INSIDE the repo — and
    `isolate` refuses that, correctly, because mirroring a tree into itself recurses. So
    every `athena mutate` without an explicit --mirror died on the safety rail meant to
    protect it. The rail was right and the default was wrong.
    """
    name = pathlib.Path(repo).resolve().name or "repo"
    return str(pathlib.Path(tempfile.gettempdir()) / f"athena-mutation-{name}")


def isolate(repo: str, mirror: str, *, skip: frozenset = frozenset(_SKIP_DIRS)) -> str:
    """EFFECTFUL: mirror the repo into a scratch tree so mutation never touches the original.

    This is the answer to a harness that was killed twice mid-mutation. A copy costs a
    second; a mutant left in `lib/` costs trust in every green run after it.

    It is also `rm -rf` pointed at a user-supplied path, and an audit demonstrated the
    consequence: `--mirror vendor` silently DELETED the vendor directory of the repo under
    test and reported success. So a destination is now refused unless it is empty, absent,
    or a previous mirror of ours (it carries `.athena-mirror`), and never inside the repo.
    """
    src, dst = pathlib.Path(repo).resolve(), pathlib.Path(mirror).resolve()
    if dst == src or src in dst.parents:
        raise UnsafeMirror(f"refusing to mirror into the repo itself: {dst}")
    if dst.exists():
        if not dst.is_dir():
            raise UnsafeMirror(f"refusing to overwrite a file: {dst}")
        if any(dst.iterdir()) and not (dst / MIRROR_MARKER).exists():
            raise UnsafeMirror(
                f"refusing to delete non-empty {dst}: it is not a previous athena mirror "
                f"(no {MIRROR_MARKER}). Point --mirror at a scratch directory.")
        shutil.rmtree(dst, ignore_errors=True)
    shutil.copytree(src, dst, ignore=shutil.ignore_patterns(*skip), dirs_exist_ok=False)
    (dst / MIRROR_MARKER).write_text("written by lib/mutation.isolate\n", encoding="utf-8")
    return str(dst)


def snapshot(targets: dict, *, lock_path: str = LOCK) -> str:
    """EFFECTFUL: write the pristine sources to disk BEFORE the first mutation.

    Kept for in-place callers. `finally` cannot survive a kill, so recovery has to belong to
    the next invocation rather than to the process that died.
    """
    p = pathlib.Path(lock_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps({"schema": "athena.mutation_lock/1",
                             "files": {path: spec["source"] for path, spec in targets.items()}},
                            ensure_ascii=False, indent=2, sort_keys=True) + "\n",
                 encoding="utf-8")
    return str(p)


def recover(*, lock_path: str = LOCK, writer=None) -> tuple[str, ...]:
    """EFFECTFUL: put every snapshotted file back and drop the lock. Safe to call always."""
    p = pathlib.Path(lock_path)
    if not p.exists():
        return ()
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return ()
    if writer is None:
        def writer(path, text):
            pathlib.Path(path).write_text(text, encoding="utf-8")
    restored = []
    for path, text in sorted((data.get("files") or {}).items()):
        writer(path, text)
        restored.append(path)
    p.unlink()
    return tuple(restored)


def target_lines(clause_map: dict, *, clause_prefix: str = "", only: str = "all") -> dict:
    """PURE: {path: frozenset(lines)} the sweep should attack.

    A full sweep over every owned line is not a thing anyone runs: this contract owns 1657
    lines, and a line owned by twenty clauses costs twenty spec runs per mutant. So the
    selector is part of the measure, not a convenience:

      all           every line the selected clauses own
      exclusive     lines exactly one clause owns — unambiguous attribution and one spec to
                    run, which makes it the cheapest honest sweep
      half-proved   lines the branch layer flagged: owned, but with an arm nothing took.
                    Branch coverage is the cheap detector, mutation the expensive confirmer,
                    and this is the wire between them.

    Filters compose with `+`. `exclusive+half-proved` is the sharpest sweep this contract
    admits — on 1716 owned lines it selects 26: suspect by branch evidence, owned by exactly
    one clause, so one spec run decides each and the verdict needs no attribution argument.
    """
    wanted = [f.strip() for f in only.split("+") if f.strip()]
    if not wanted or any(f not in ("all", "exclusive", "half-proved") for f in wanted):
        raise ValueError(f"refused: unknown target selector {only!r}")
    clauses = (clause_map or {}).get("clauses") or {}
    picked = {cid: files for cid, files in clauses.items()
              if not clause_prefix or cid.startswith(clause_prefix)}

    if "half-proved" in wanted:
        source = {cid: (clause_map.get("partial") or {}).get(cid) or {} for cid in picked}
    else:
        source = picked

    owners_count: dict = {}
    if "exclusive" in wanted:
        for files in clauses.values():
            for path, lines in files.items():
                for ln in lines:
                    owners_count[(path, ln)] = owners_count.get((path, ln), 0) + 1

    out: dict = {}
    for files in source.values():
        for path, lines in files.items():
            keep = [ln for ln in lines
                    if "exclusive" not in wanted or owners_count.get((path, ln)) == 1]
            if keep:
                out[path] = out.get(path, frozenset()) | frozenset(keep)
    return out


def red_specs(spec_cmds: dict, ledger: dict | None) -> tuple[str, ...]:
    """PURE: the run_cmds of specs the ledger already recorded as failing.

    The cheap half of `baseline`. Re-running every candidate on clean source costs a second
    full suite; the ledger is an artifact this repo maintains anyway and answers the same
    question. A spec with NO verdict is deliberately not excluded — unknown is not red, and
    silently dropping unrun specs would gut the sweep whenever the ledger lags.
    """
    idx = {r.get("scenario", ""): r for r in (ledger or {}).get("results", [])}
    return tuple(sorted({cmd for sid, (_, cmd) in spec_cmds.items()
                         if sid in idx and not idx[sid].get("passed")}))


def baseline(spec_cmds: dict, cmds, *, runner) -> tuple[str, ...]:
    """EFFECTFUL: which of these specs are RED before anything is mutated.

    Without this, `hunt` reads any non-zero exit as "the spec noticed" — including a spec
    that was already failing, or a collection error, or a missing dependency. An audit
    proved the consequence: a mutant was reported killed by a spec that never passed in the
    first place. A spec that is red on clean source cannot be a witness.
    """
    from lib.verification import outcome
    return tuple(cmd for cmd in dict.fromkeys(cmds) if outcome(runner(cmd)).status != "PASS")


def hunt(clause_map: dict, spec_cmds: dict, targets: dict, *, runner, writer,
         limit_per_line: int = 1, max_mutants: int = 0,
         max_specs: int = 0, exclude: tuple[str, ...] = (), verify_baseline: bool = False) -> tuple[dict, ...]:
    """EFFECTFUL: build mutants, run each against its owners' specs, stop at first killer.

    `runner(cmd) -> int` and `writer(path, text) -> None` are injected, so the caller decides
    WHERE this happens — and the CLI points both at an isolated mirror, never at the repo.
    """
    from lib.verification import outcome
    results: list[dict] = []
    clean: dict = {}
    for path, spec in sorted(targets.items()):
        original, lines = spec["source"], spec["lines"]
        per_line: dict[int, int] = {}
        for mut in mutants(original, lines, path=path):
            if per_line.get(mut.line, 0) >= limit_per_line:
                continue
            if max_mutants and len(results) >= max_mutants:
                results[0]["budget_exhausted"] = True
                return tuple(results)
            per_line[mut.line] = per_line.get(mut.line, 0) + 1
            cmds = tuple(c for c in scoped_specs(clause_map, spec_cmds, path, mut.line)
                         if c not in exclude)
            if not cmds:
                # No spec owns this line, so nothing was asked to notice the break. Calling
                # that "survived" asserts a vacuity nobody tested — an audit caught exactly
                # this: `0 >= 0` classed a never-run mutant as a survivor.
                results.append({"path": path, "line": mut.line, "kind": mut.kind,
                                "specs_run": 0, "specs_total": 0, "status": "unowned",
                                "killed": False, "killer": ""})
                continue
            budget = cmds[:max_specs] if max_specs else cmds
            if verify_baseline:
                for cmd in budget:
                    if cmd not in clean:
                        clean[cmd] = outcome(runner(cmd))
                if any(clean[c].status != "PASS" for c in budget):
                    results.append({"path": path, "line": mut.line, "kind": mut.kind,
                                    "specs_run": 0, "specs_total": len(cmds), "status": "baseline_error",
                                    "killed": False, "killer": "", "reason": "baseline not green"})
                    continue
            killed, killer, ran = False, "", 0
            errors = []
            try:
                writer(path, mut.source)
                for cmd in budget:
                    ran += 1
                    result = outcome(runner(cmd))
                    if result.status != "PASS":
                        killed, killer = True, cmd
                        break
                    if result.status != "PASS":
                        errors.append({"cmd": cmd, "exit_code": result.exit_code, "tail": result.tail})
            finally:
                writer(path, original)
            # THREE outcomes, not two. A line owned by 129 clauses cannot be swept inside a
            # CI budget, and calling the leftover "survived" would manufacture vacuity claims
            # nobody checked. Undetermined is the honest third state.
            status = "killed" if killed else ("tool_error" if errors else (
                "survived" if ran >= len(cmds) else "undetermined"))
            results.append({"path": path, "line": mut.line, "kind": mut.kind,
                            "specs_run": ran, "specs_total": len(cmds),
                            "status": status, "killed": killed, "killer": killer, "errors": errors,
                            "witness_clauses": sorted({cid for cid, cmd in spec_cmds.values() if killed and cmd == killer})})
    return tuple(results)

