        "PASS" if rows and all(r["state"] == "PASS" for r in rows) else "INCOMPLETE")
    challenges = [v for r in rows for v in r["challenges"]]
    metrics = {"clauses": len(rows), "valid_controls": sum(v["kind"] == "valid" for v in challenges),
