        commands = [specs[sid].run_cmd for sid in p["specs"]]
        baseline = [execute(inputs, {}, cmd, timeout=timeout, runner=runner) for cmd in commands]
        challenges = []
        for v in p.get("variants", []):
            row = {"id": v["id"], "kind": v["kind"], "state": "INCOMPLETE", "checks": []}
